public class Main {
    public static int add(int a, int b) {
        int sum = a + b;
        return sum;
    }

    public static int square(int n) {
        return n * n;
    }

    public static void main(String[] args) {
        int result = add(3, 7);
        System.out.println("3 + 7 = " + result);

        int squared = square(5);
        System.out.println("5^2 = " + squared);
    }
}
